export default function Navbar({ onNavigate, onLogout, user }) {
  
  const scrollTo = (id) => {
    const el = document.getElementById(id);
    if (el) el.scrollIntoView({ behavior: "smooth" });
  };

  return (
    <nav className="nav">
      <div className="brand" onClick={() => scrollTo("home-section")}>NGO Portal</div>

      <div className="links">
        <button onClick={() => scrollTo("home-section")}>Home</button>
        <button onClick={() => scrollTo("about-section")}>About Us</button>
        <button onClick={() => scrollTo("events-section")}>Events</button>
        <button onClick={() => scrollTo("contact-section")}>Contact</button>

        {!user && <button onClick={() => onNavigate("login")}>Login</button>}
        {!user && <button onClick={() => onNavigate("register")}>Register</button>}
        {user && <button onClick={() => onNavigate("dashboard")}>Dashboard</button>}
        {user && <button onClick={onLogout}>Logout</button>}
      </div>
    </nav>
  );
}
